const account = $('Normalize Account Payload').first().json;
let parsedEvaluation = {};
try {
  const rawOutput = $input.first().json.message?.content || $input.first().json.response || '{}';
  parsedEvaluation = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
} catch (e) {
  parsedEvaluation = { lead_score: 50, tier: 'Tier C', error: e.message };
}

return [{
  json: {
    ...account,
    qualification: parsedEvaluation
  }
}];

