const prospect = $('Format Scored Lead').first().json;
let outreachCopy = {};
try {
  const raw = $input.first().json.message?.content || '{}';
  outreachCopy = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  outreachCopy = { error: 'Failed to parse outreach copy' };
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    status: "AWAITING_HUMAN_APPROVAL",
    company: prospect.company_name,
    contact: `${prospect.decision_maker_name} (${prospect.decision_maker_title})`,
    email: prospect.decision_maker_email,
    score: prospect.qualification.lead_score,
    tier: prospect.qualification.tier,
    service: prospect.qualification.recommended_service,
    wedge: prospect.qualification.wedge_offer,
    drafted_copy: outreachCopy
  }
}];
